descriptor.templateCss:
/* General Styles */
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
  display: flex;
  background-color: #1f315e; /* Dark Blue Background */
}

.sidebar {
  width: 250px;
  background-color: #1f315e; /* Sidebar Background Color */
  color: white; /* Sidebar Text Color */
  padding-top: 20px;
  position: fixed; /* Fixed Sidebar */
  top: 0;
  left: 0;
  height: 100vh; /* Full-height */
}

.logo img {
  width: 200px;
  height: auto;
  margin-bottom: 20px;
}

.sidebar ul {
  list-style-type: none;
  padding: 0;
}

.sidebar ul li {
  width: 100%;
}

.sidebar ul li span {
  display: block;
  padding: 10px 20px;
  text-decoration: none;
  color: white; /* Menu Item Text Color */
  font-size: 18px;
  background-color: #1f315e; /* Menu Item Background Color */
  border: 1px solid #1a8ec3; /* Slightly darker border */
}

.sidebar ul li span:hover {
  background-color: #1a8ec3; /* Darker blue on hover */
  font-weight: bold; /* Bold text on hover */
}

#main-content {
  margin-left: 250px; /* Offset for the fixed sidebar */
  padding: 20px;
  width: 100%;
}

#main-content h1 {
  font-size: 24px;
  color: white; /* Main Content Title Color */
}

#main-content p {
  font-size: 16px;
  color: white; /* Main Content Text Color */
}

descriptor.controllerScript:
document.addEventListener('DOMContentLoaded', () => {
  // Function to load content into the main content area
  function loadContent(contentId) {
    const content = {
      picture: `
        <h1>Picture Settings</h1>
        <p>Adjust the brightness, contrast, and color settings of your display.</p>
      `,
      osd: `
        <h1>OnScreen Display</h1>
        <p>Customize the on-screen display settings, including position, transparency, and timeout.</p>
      `,
      sound: `
        <h1>Sound Settings</h1>
        <p>Modify the volume, balance, and equalizer settings for optimal audio experience.</p>
      `,
      network: `
        <h1>Network Settings</h1>
        <p>Configure network connections, including Wi-Fi and Ethernet settings.</p>
      `,
      system: `
        <h1>System Settings</h1>
        <p>Manage system preferences such as language, time zone, and firmware updates.</p>
      `,
      support: `
        <h1>Support</h1>
        <p>Access user manuals, troubleshooting guides, and contact support information.</p>
      `
    };

    const mainContent = document.getElementById('main-content');
    mainContent.innerHTML = content[contentId] || '<p>Content not available.</p>';
  }

  // Add event listeners to each sidebar menu item
  document.querySelector('.menu-item[data-menu="picture"]').addEventListener('click', () => loadContent('picture'));
  document.querySelector('.menu-item[data-menu="osd"]').addEventListener('click', () => loadContent('osd'));
  document.querySelector('.menu-item[data-menu="sound"]').addEventListener('click', () => loadContent('sound'));
  document.querySelector('.menu-item[data-menu="network"]').addEventListener('click', () => loadContent('network'));
  document.querySelector('.menu-item[data-menu="system"]').addEventListener('click', () => loadContent('system'));
  document.querySelector('.menu-item[data-menu="support"]').addEventListener('click', () => loadContent('support'));

  // Optionally, load default content or a welcome message
  loadContent('picture');
});

